import time
import os

class Player:
    def __init__(self):
        self.x = 0
        self.y = 0

class Game:
    def __init__(self):
        self.player = Player()
        self.obstacles = [[False, False, False, False], [False, False, False, False], [False, False, False, False], [False, False, False, False]]
        self.treasure = (3, 3)
        self.obstacles[self.treasure[1]][self.treasure[0]] = True
        self.obstacles[self.player.y][self.player.x] = True
        self.time_limit = 60  # seconds
        self.time_start = time.time()

    def move_player(self, direction):
        if direction == 'up' and self.player.y > 0 and not self.obstacles[self.player.y-1][self.player.x]:
            self.player.y -= 1
            self.obstacles[self.player.y][self.player.x] = True
        elif direction == 'down' and self.player.y < 3 and not self.obstacles[self.player.y+1][self.player.x]:
            self.player.y += 1

